function freeAt(entries, lesson, slot) {
    const covers = (e) => e.day === lesson.day && e.id !== lesson.id && e.slot < slot + lesson.length && slot < e.slot + e.length;
    const busy = entries.some((e) => covers(e) && (e.groupId === lesson.groupId || (e.teacherId && e.teacherId === lesson.teacherId) || (e.roomId && e.roomId === lesson.roomId)));
    const nextTo = entries.some((e) => e.day === lesson.day && e.groupId === lesson.groupId && e.subjectId === lesson.subjectId && e.id !== lesson.id && (e.slot + e.length === slot || slot + lesson.length === e.slot));
    return !busy && !nextTo && slot + lesson.length <= 32;
}
